/**
 * @file scenes.c
 * @brief 场景注册表。
 */

#include <stdio.h>
#include <string.h>

#include "sim.h"

#ifdef SIM_WITH_UI
/**
 * @brief `ui` 场景：把屏幕交给 vendor 的真实自行车 UI。
 *
 * 这里**不建任何控件** —— `sim_ui_start()` 会照板端 `bicycle_c_main.c` 的
 * 顺序初始化页面管理器、压开机 splash，并用定时器接管后续每拍工作。
 * 屏幕尺寸用启动参数（默认 240x320，与设备一致）。
 */
static void scene_ui_create(lv_obj_t *scr, const sim_cfg_t *cfg)
{
    (void)scr;
    /* 巡页（--ui-tour）只影响 `ui` 场景；未配置时 sim_ui_start 行为不变。 */
    sim_ui_tour_configure(cfg->ui_tour, cfg->tour_frames);
    sim_ui_start();
}
#endif

static const sim_scene_t s_scenes[] = {
    { "demo",      "控件总览：按钮/滑杆/开关/图表/中文字体", scene_demo_create },
    /* WP-DESIGN/R1：240x320 码表设计提案，三屏用 SIM_DESIGN_SCREEN 选。 */
    { "design-a",  "设计提案 A 留白极简：待机/骑行/菜单", scene_design_a_create },
    { "design-b",  "设计提案 B 数据仪表：待机/骑行/菜单", scene_design_b_create },
    { "design-c",  "设计提案 C 赛博仪表：待机/骑行/菜单", scene_design_c_create },
#ifdef SIM_WITH_UI
    /* `vmap` = 真 vmap 组件：读 mkfs/fat/map 的 z14 网格包，鼠标拖动/滚轮缩放，
     * HUD 显示 lon/lat/scale/viewport/中心图标（见 ui_port/scene_vmap_live.c）。 */
    { "vmap",      "真 vmap 组件：z14 网格包 + 拖动/缩放 + HUD", scene_vmap_live_create },
#endif
    { "vmap-mock", "vmap 底图 mock：RGB565 canvas + 直接光栅化 + 中文标注", scene_vmap_create },
#ifdef SIM_WITH_UI
    { "ui",   "真实自行车 UI（vendor ui/bicycle）：开机 splash → 主界面", scene_ui_create },
#endif
};

#define SCENE_COUNT (sizeof(s_scenes) / sizeof(s_scenes[0]))

const sim_scene_t *sim_scene_find(const char *name)
{
    if (!name) {
        return NULL;
    }
    for (size_t i = 0; i < SCENE_COUNT; i++) {
        if (strcmp(s_scenes[i].name, name) == 0) {
            return &s_scenes[i];
        }
    }
    return NULL;
}

void sim_scene_list(void)
{
    puts("可用场景:");
    for (size_t i = 0; i < SCENE_COUNT; i++) {
        printf("  %-8s %s\n", s_scenes[i].name, s_scenes[i].desc);
    }
}

/**
 * @file scene_design_a.c
 * @brief WP-DESIGN 方案 A「留白极简」：暖白纸、发丝线、大圆角卡片、超大数字。
 *
 * 三个屏幕由 SIM_DESIGN_SCREEN=standby|ride|menu 选择（见 design_common.h）。
 * 纯 LVGL 控件：obj/label/line，无位图、无自定义 draw。
 */

#include <stdio.h>

#include "design_common.h"

/* ── 色板（暖白 / 单一暖橙）────────────────────────────────────── */
#define A_BG      0xF6F2EBu   /**< 暖白纸 */
#define A_CARD    0xFFFFFFu   /**< 卡片 */
#define A_INK     0x17181Au   /**< 主文字 */
#define A_MUTE    0x8C8A86u   /**< 次要文字 */
#define A_ACCENT  0xFF6E12u   /**< 唯一强调色（暖橙） */
#define A_TINT    0xFFF0E4u   /**< 选中行淡橙 */
#define A_WHITE   0xFFFFFFu

/** 发丝线：8% 黑（1px，无色块填充感）。 */
static void a_hair_h(lv_obj_t *p, int x, int y, int w)
{
    d_hline(p, x, y, w, 0x000000u, 20);
}

static void a_hair_v(lv_obj_t *p, int x, int y, int h)
{
    d_vline(p, x, y, h, 0x000000u, 20);
}

/** 底部胶囊按键提示（A 的固定语言：一枚胶囊，不是按钮阵列）。 */
static void a_capsule(lv_obj_t *scr, int y, const char *txt, int px)
{
    const int x = 16;
    const int w = 208;
    const int h = 30;

    d_box(scr, x, y, w, h, A_ACCENT, LV_OPA_COVER, h / 2);
    lv_obj_t *row = d_stack(scr, x, y, w, h, LV_FLEX_ALIGN_CENTER, 0);

    lv_obj_t *l = lv_label_create(row);
    lv_label_set_text(l, txt);
    lv_obj_set_style_text_font(l, sim_font_cjk(px), 0);
    lv_obj_set_style_text_color(l, lv_color_hex(A_WHITE), 0);
}

/** 图标位：20x20 细描边圆角方块 + 内部几何形（0 点 / 1 圆 / 2 方 / 3 竖条）。 */
static void a_icon(lv_obj_t *p, int x, int y, int kind, uint32_t color, bool filled)
{
    lv_obj_t *box = d_box(p, x, y, 20, 20, 0x000000u, LV_OPA_TRANSP, 6);

    lv_obj_set_style_border_width(box, 1, 0);
    lv_obj_set_style_border_color(box, lv_color_hex(color), 0);
    lv_obj_set_style_border_opa(box, LV_OPA_COVER, 0);

    switch (kind) {
        case 0:
            d_box(box, 7, 7, 6, 6, color, LV_OPA_COVER, 3);
            break;
        case 1:
            d_box(box, 6, 6, 8, 8, filled ? color : 0x000000u,
                  filled ? LV_OPA_COVER : LV_OPA_TRANSP, 4);
            if (!filled) {
                d_box(box, 6, 6, 8, 8, 0x000000u, LV_OPA_TRANSP, 4);
            }
            break;
        case 2:
            d_box(box, 6, 7, 8, 6, color, filled ? LV_OPA_COVER : LV_OPA_40, 1);
            break;
        default:
            d_box(box, 9, 5, 2, 10, color, LV_OPA_COVER, 1);
            break;
    }
    if (kind == 1 && !filled) {
        /* 空心圆：用 1px 描边的圆角方块近似 */
        lv_obj_t *ring = d_box(box, 6, 6, 8, 8, 0x000000u, LV_OPA_TRANSP, 4);

        lv_obj_set_style_border_width(ring, 1, 0);
        lv_obj_set_style_border_color(ring, lv_color_hex(color), 0);
        lv_obj_set_style_border_opa(ring, LV_OPA_COVER, 0);
    }
}

/** 数值 + 单位（同一行，单位在底线上）。 */
static void a_value_unit(lv_obj_t *p, int x, int y, int w,
                         const char *val, const char *unit, int val_px,
                         uint32_t color)
{
    lv_obj_t *row = d_stack(p, x, y, w, 30, LV_FLEX_ALIGN_START, 3);

    lv_obj_t *v = lv_label_create(row);

    lv_label_set_text(v, val);
    lv_obj_set_style_text_font(v, sim_font_cjk(val_px), 0);
    lv_obj_set_style_text_color(v, lv_color_hex(color), 0);

    if (unit && unit[0]) {
        lv_obj_t *u = lv_label_create(row);

        lv_label_set_text(u, unit);
        lv_obj_set_style_text_font(u, sim_font_cjk(11), 0);
        lv_obj_set_style_text_color(u, lv_color_hex(A_MUTE), 0);
        lv_obj_set_style_pad_bottom(u, 4, 0);
    }
}

/* ── 待机 ──────────────────────────────────────────────────────── */

static void a_standby(lv_obj_t *scr)
{
    d_bg(scr, A_BG);

    d_label(scr, "上午", 12, A_MUTE, 20, 13);
    d_dot(scr, 174, 21, 4, A_MUTE);
    d_label(scr, "GPS 12", 12, A_MUTE, 182, 13);

    /* 时间卡片 */
    d_box(scr, 16, 40, 208, 136, A_CARD, LV_OPA_COVER, 20);
    lv_obj_t *trow = d_stack(scr, 34, 42, 172, 92, LV_FLEX_ALIGN_START, 0);
    lv_obj_t *time = lv_label_create(trow);

    lv_label_set_text(time, "8:42");
    lv_obj_set_style_text_font(time, sim_font_cjk(76), 0);
    lv_obj_set_style_text_color(time, lv_color_hex(A_INK), 0);
    lv_obj_set_style_text_letter_space(time, -1, 0);

    a_hair_h(scr, 34, 138, 172);
    d_label(scr, "10月29日 星期四", 13, A_MUTE, 34, 146);

    /* 上次骑行卡片 */
    d_box(scr, 16, 188, 208, 62, A_CARD, LV_OPA_COVER, 18);
    d_label(scr, "上次骑行", 11, A_MUTE, 32, 196);
    a_value_unit(scr, 130, 190, 78, "42.6", "km", 24, A_INK);
    a_hair_h(scr, 32, 224, 176);
    d_label(scr, "用时 1:52 · 均速 26.4 km/h", 11, A_MUTE, 32, 228);

    a_capsule(scr, 282, "短按 KEY1 菜单 · 长按 KEY2 开始", 11);
}

/* ── 骑行 ──────────────────────────────────────────────────────── */

static void a_ride(lv_obj_t *scr)
{
    d_bg(scr, A_BG);

    d_label(scr, "骑行中", 12, A_MUTE, 20, 13);
    d_label_w(scr, "1 / 3", 11, A_MUTE, 160, 14, 60, LV_TEXT_ALIGN_RIGHT);

    lv_obj_t *srow = d_stack(scr, 16, 30, 152, 94, LV_FLEX_ALIGN_START, 0);
    lv_obj_t *spd = lv_label_create(srow);

    lv_label_set_text(spd, "24.8");
    lv_obj_set_style_text_font(spd, sim_font_cjk(72), 0);
    lv_obj_set_style_text_color(spd, lv_color_hex(A_INK), 0);
    lv_obj_set_style_text_letter_space(spd, -1, 0);

    d_label(scr, "km/h", 13, A_MUTE, 176, 92);
    a_hair_h(scr, 16, 132, 208);

    /* 2x2 数据 */
    d_label(scr, "里程", 11, A_MUTE, 16, 140);
    a_value_unit(scr, 16, 152, 92, "12.4", "km", 24, A_INK);
    d_label(scr, "时间", 11, A_MUTE, 128, 140);
    a_value_unit(scr, 128, 152, 92, "00:42", "", 24, A_INK);

    a_hair_h(scr, 16, 190, 208);
    a_hair_v(scr, 120, 148, 96);

    d_label(scr, "心率", 11, A_MUTE, 16, 198);
    a_value_unit(scr, 16, 210, 92, "142", "bpm", 24, A_INK);
    d_label(scr, "踏频", 11, A_MUTE, 128, 198);
    a_value_unit(scr, 128, 210, 92, "86", "rpm", 24, A_INK);

    /* 海拔 / 坡度 */
    d_label(scr, "海拔", 11, A_MUTE, 16, 252);
    d_label(scr, "326", 18, A_INK, 46, 246);
    d_label(scr, "m", 11, A_MUTE, 80, 252);
    d_label(scr, "坡度", 11, A_MUTE, 134, 252);
    d_label(scr, "3.2", 18, A_INK, 164, 246);
    d_label(scr, "%", 11, A_MUTE, 198, 252);

    a_capsule(scr, 286, "短按 KEY1 切页 · 长按 KEY2 结束", 11);
}

/* ── 菜单 ──────────────────────────────────────────────────────── */

typedef struct {
    const char *group;
    const char *item[2];
    int icon[2];
} a_group_t;

static void a_menu_card(lv_obj_t *scr, int y, const a_group_t *g, int sel)
{
    d_box(scr, 16, y, 208, 70, A_CARD, LV_OPA_COVER, 18);
    d_label(scr, g->group, 10, A_MUTE, 32, y + 5);

    for (int i = 0; i < 2; i++) {
        const int ry = y + 18 + i * 25;
        const bool on = (sel == i);

        if (on) {
            d_box(scr, 24, ry - 1, 192, 25, A_TINT, LV_OPA_COVER, 10);
        }
        a_icon(scr, 32, ry + 1, g->icon[i], on ? A_ACCENT : A_MUTE, false);
        lv_obj_t *txt = d_label(scr, g->item[i], 14, on ? A_ACCENT : A_INK,
                                60, ry + 2);
        if (on) {
            lv_obj_set_style_text_letter_space(txt, 0, 0);
        }
        d_chevron(scr, 196, ry + 6, on ? A_ACCENT : A_MUTE, 8);
    }
}

static void a_menu(lv_obj_t *scr)
{
    static const a_group_t route = { "路线", { "路线规划", "历史记录" }, { 0, 1 } };
    static const a_group_t dev = { "设备", { "传感器", "显示" }, { 2, 3 } };
    static const a_group_t sys = { "系统", { "关于", "关机" }, { 1, 0 } };

    d_bg(scr, A_BG);

    d_label(scr, "菜单", 26, A_INK, 20, 10);
    d_label_w(scr, "3 组 · 6 项", 11, A_MUTE, 140, 24, 80, LV_TEXT_ALIGN_RIGHT);

    a_menu_card(scr, 50, &route, 0);
    a_menu_card(scr, 126, &dev, -1);
    a_menu_card(scr, 202, &sys, -1);

    a_capsule(scr, 282, "KEY1 短按切换 / 长按确认 · KEY2 返回", 11);
}

/* ── 场景入口 ──────────────────────────────────────────────────── */

static void design_a_build(lv_obj_t *scr, int screen)
{
    switch (screen) {
        case DESIGN_SCREEN_RIDE: a_ride(scr); break;
        case DESIGN_SCREEN_MENU: a_menu(scr); break;
        default: a_standby(scr); break;
    }
}

void scene_design_a_create(lv_obj_t *scr, const sim_cfg_t *cfg)
{
    (void)cfg;
    d_scene_start(scr, design_a_build);
}

/**
 * @file design_common.c
 * @brief WP-DESIGN/R1 共用绘图小工具 + 场景启动/切屏。
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "design_common.h"

/* ── 画布 ──────────────────────────────────────────────────────── */

void d_bg(lv_obj_t *scr, uint32_t hex)
{
    lv_obj_remove_style_all(scr);
    lv_obj_set_style_bg_color(scr, lv_color_hex(hex), 0);
    lv_obj_set_style_bg_opa(scr, LV_OPA_COVER, 0);
    lv_obj_remove_flag(scr, LV_OBJ_FLAG_SCROLLABLE);
}

lv_obj_t *d_box(lv_obj_t *parent, int x, int y, int w, int h,
                uint32_t hex, lv_opa_t opa, int radius)
{
    lv_obj_t *o = lv_obj_create(parent);

    lv_obj_remove_style_all(o);
    lv_obj_set_pos(o, x, y);
    lv_obj_set_size(o, w, h);
    lv_obj_set_style_bg_color(o, lv_color_hex(hex), 0);
    lv_obj_set_style_bg_opa(o, opa, 0);
    lv_obj_set_style_radius(o, radius, 0);
    lv_obj_remove_flag(o, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(o, LV_OBJ_FLAG_CLICKABLE);
    return o;
}

lv_obj_t *d_hline(lv_obj_t *parent, int x, int y, int w,
                  uint32_t hex, lv_opa_t opa)
{
    return d_box(parent, x, y, w, 1, hex, opa, 0);
}

lv_obj_t *d_vline(lv_obj_t *parent, int x, int y, int h,
                  uint32_t hex, lv_opa_t opa)
{
    return d_box(parent, x, y, 1, h, hex, opa, 0);
}

void d_dot(lv_obj_t *parent, int x, int y, int size, uint32_t hex)
{
    (void)d_box(parent, x, y, size, size, hex, LV_OPA_COVER, size / 2);
}

lv_obj_t *d_label(lv_obj_t *parent, const char *txt, int px, uint32_t hex,
                  int x, int y)
{
    lv_obj_t *l = lv_label_create(parent);

    lv_label_set_text(l, txt);
    lv_label_set_long_mode(l, LV_LABEL_LONG_CLIP);
    lv_obj_set_style_text_font(l, sim_font_cjk(px), 0);
    lv_obj_set_style_text_color(l, lv_color_hex(hex), 0);
    lv_obj_set_pos(l, x, y);
    return l;
}

lv_obj_t *d_label_w(lv_obj_t *parent, const char *txt, int px, uint32_t hex,
                    int x, int y, int w, lv_text_align_t align)
{
    lv_obj_t *l = d_label(parent, txt, px, hex, x, y);

    lv_obj_set_width(l, w);
    lv_obj_set_style_text_align(l, align, 0);
    return l;
}

lv_obj_t *d_stack(lv_obj_t *parent, int x, int y, int w, int h,
                  lv_flex_align_t main_align, int gap)
{
    lv_obj_t *c = lv_obj_create(parent);

    lv_obj_remove_style_all(c);
    lv_obj_set_pos(c, x, y);
    lv_obj_set_size(c, w, h);
    lv_obj_set_flex_flow(c, LV_FLEX_FLOW_ROW);
    lv_obj_set_flex_align(c, main_align, LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);
    lv_obj_set_style_pad_column(c, gap, 0);
    lv_obj_remove_flag(c, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_remove_flag(c, LV_OBJ_FLAG_CLICKABLE);
    return c;
}

void d_chevron(lv_obj_t *parent, int x, int y, uint32_t hex, int h)
{
    static const lv_point_precise_t small[] = { { 0, 0 }, { 4, 4 }, { 0, 8 } };
    static const lv_point_precise_t big[] = { { 0, 0 }, { 6, 6 }, { 0, 12 } };
    lv_obj_t *line = lv_line_create(parent);

    lv_obj_remove_style_all(line);
    lv_line_set_points(line, h > 8 ? big : small, 3);
    lv_obj_set_style_line_width(line, 1, 0);
    lv_obj_set_style_line_color(line, lv_color_hex(hex), 0);
    lv_obj_set_style_line_rounded(line, false, 0);
    lv_obj_set_pos(line, x, y);
    lv_obj_remove_flag(line, LV_OBJ_FLAG_CLICKABLE);
}

/* ── 场景 ──────────────────────────────────────────────────────── */

int d_screen_from_env(void)
{
    const char *s = getenv("SIM_DESIGN_SCREEN");

    if (!s || !s[0]) {
        return DESIGN_SCREEN_STANDBY;
    }
    if (strcmp(s, "ride") == 0 || strcmp(s, "1") == 0) {
        return DESIGN_SCREEN_RIDE;
    }
    if (strcmp(s, "menu") == 0 || strcmp(s, "2") == 0) {
        return DESIGN_SCREEN_MENU;
    }
    if (strcmp(s, "standby") != 0 && strcmp(s, "0") != 0) {
        fprintf(stderr, "sim: unknown SIM_DESIGN_SCREEN=%s (standby|ride|menu)\n", s);
    }
    return DESIGN_SCREEN_STANDBY;
}

static void (*s_build)(lv_obj_t *, int);
static lv_obj_t *s_scr;

/** 递归数控件：给 DESIGN.md 的实现代价一个真实数字。 */
static int count_objs(lv_obj_t *o)
{
    int n = 1;
    const uint32_t c = lv_obj_get_child_count(o);

    for (uint32_t i = 0; i < c; i++) {
        n += count_objs(lv_obj_get_child(o, (int32_t)i));
    }
    return n;
}

static void design_build_now(int screen)
{
    lv_obj_clean(s_scr);
    s_build(s_scr, screen);
    printf("design: screen=%d objects=%d\n", screen, count_objs(s_scr));
    fflush(stdout);
}

static void design_key_timer(lv_timer_t *t)
{
    (void)t;
    for (;;) {
        int k = sim_display_take_raw_key();

        if (k == 0) {
            break;
        }
        if ((k >= '1' && k <= '3') && s_scr && s_build) {
            design_build_now(k - '1');
        }
    }
}

void d_scene_start(lv_obj_t *scr, design_build_fn_t build)
{
    s_scr = scr;
    s_build = build;
    design_build_now(d_screen_from_env());
    /* 窗口模式下 1/2/3 切三屏；headless 无按键，定时器空转。 */
    lv_timer_create(design_key_timer, 60, NULL);
}

