/**
 * @file scene_design_b.c
 * @brief WP-DESIGN 方案 B「数据仪表」：近黑底、等宽右对齐数字、3px 色条分栏、
 *        20px 窄状态栏、底部区间条、单一青绿强调色。
 *
 * 三个屏幕由 SIM_DESIGN_SCREEN=standby|ride|menu 选择（见 design_common.h）。
 * 纯 LVGL 控件：obj/label/line，无位图、无自定义 draw。
 */

#include "design_common.h"

/* ── 色板（近黑 / 单一青绿）────────────────────────────────────── */
#define B_BG      0x0B0C0Eu   /**< 近黑底 */
#define B_TEXT    0xF4F7F8u   /**< 主数据 */
#define B_MID     0xB9C2C9u   /**< 次级正文 */
#define B_DIM     0x7C858Eu   /**< 标签 */
#define B_DIM2    0x3A4249u   /**< 非活动色条 / 刻度 */
#define B_LINE    0x1E2328u   /**< 分隔线 */
#define B_TRACK   0x1B2025u   /**< 进度底 */
#define B_ACCENT  0x00D1B2u   /**< 唯一强调色（青绿） */
#define B_SEL     0x0F181Au   /**< 选中行底 */

static void b_hline(lv_obj_t *p, int x, int y, int w)
{
    d_hline(p, x, y, w, B_LINE, LV_OPA_COVER);
}

/** 20px 窄状态栏：左标题、右 GPS。 */
static void b_status(lv_obj_t *scr, const char *left, const char *right, bool gps)
{
    d_label(scr, left, 10, B_MID, 12, 2);
    if (gps) {
        d_dot(scr, 172, 8, 4, B_ACCENT);
        d_label_w(scr, right, 10, B_DIM, 180, 2, 48, LV_TEXT_ALIGN_RIGHT);
    } else {
        d_label_w(scr, right, 10, B_DIM, 140, 2, 88, LV_TEXT_ALIGN_RIGHT);
    }
    b_hline(scr, 0, 20, 240);
}

/** 细进度条。 */
static void b_bar(lv_obj_t *p, int x, int y, int w, int h, int pct,
                  uint32_t fill, uint32_t track)
{
    int fw = w * pct / 100;

    d_box(p, x, y, w, h, track, LV_OPA_COVER, h / 2);
    if (fw > 0) {
        d_box(p, x, y, fw, h, fill, LV_OPA_COVER, h / 2);
    }
}

/**
 * @brief 等宽数字：每个字符一个固定宽 cell，整体右对齐到 x_right。
 *
 * MiSans 的数字是比例字宽（"1111" 比 "8888" 窄 34%），骑行读数会左右跳。
 * 这里按 cell 逐字定位：数字 cell = 0.64em，冒号/小数点 = 0.34em，
 * 视觉上就是等宽表盘数字，且不需要额外烘一套等宽字库。
 */
static void b_num(lv_obj_t *p, int x_right, int y, int px, const char *s,
                  uint32_t color)
{
    const int dcell = (px * 41 + 32) / 64;
    const int pcell = (px * 22 + 32) / 64;
    int total = 0;

    for (const char *c = s; *c; c++) {
        total += (*c == ':' || *c == '.') ? pcell : dcell;
    }

    int x = x_right - total;

    for (const char *c = s; *c; c++) {
        const int cell = (*c == ':' || *c == '.') ? pcell : dcell;
        char buf[2] = { *c, 0 };
        lv_obj_t *l = d_label(p, buf, px, color, x, y);

        lv_obj_set_width(l, cell);
        lv_obj_set_style_text_align(l, LV_TEXT_ALIGN_CENTER, 0);
        x += cell;
    }
}

/** 数据块：3px 色条 + 左标签 + 右对齐数值/单位。 */
static void b_metric(lv_obj_t *p, int x, int y, int w,
                     const char *label, const char *val, const char *unit,
                     bool active)
{
    d_box(p, x, y + 2, 3, 24, active ? B_ACCENT : B_DIM2, LV_OPA_COVER, 0);
    d_label(p, label, 10, B_DIM, x + 10, y + 6);

    if (unit && unit[0]) {
        b_num(p, x + w - 30, y - 1, 18, val, active ? B_ACCENT : B_TEXT);
        d_label_w(p, unit, 9, B_DIM, x + w - 26, y + 11, 18, LV_TEXT_ALIGN_RIGHT);
    } else {
        b_num(p, x + w - 8, y - 1, 18, val, active ? B_ACCENT : B_TEXT);
    }
}

/** 图标位：18x18 细描边方 + 内部几何形。 */
static void b_icon(lv_obj_t *p, int x, int y, int kind, uint32_t color)
{
    lv_obj_t *box = d_box(p, x, y, 18, 18, 0x000000u, LV_OPA_TRANSP, 4);

    lv_obj_set_style_border_width(box, 1, 0);
    lv_obj_set_style_border_color(box, lv_color_hex(color), 0);
    lv_obj_set_style_border_opa(box, LV_OPA_COVER, 0);

    switch (kind) {
        case 0: d_box(box, 6, 6, 6, 6, color, LV_OPA_COVER, 3); break;
        case 1: {
            lv_obj_t *ring = d_box(box, 5, 5, 8, 8, 0x000000u, LV_OPA_TRANSP, 4);

            lv_obj_set_style_border_width(ring, 1, 0);
            lv_obj_set_style_border_color(ring, lv_color_hex(color), 0);
            lv_obj_set_style_border_opa(ring, LV_OPA_COVER, 0);
            break;
        }
        case 2: d_box(box, 5, 6, 8, 6, color, LV_OPA_COVER, 1); break;
        default: d_box(box, 8, 4, 2, 10, color, LV_OPA_COVER, 1); break;
