 * @file design2_common.h
 * @brief WP-DESIGN2/R1：D/E/F 三套新信息架构共用的四屏选择 + 几何小工具。
 *
 * 画布/文字小工具直接复用 design_common.h（d_bg/d_box/d_label/d_stack…），
 * 本文件只补四屏（main/ride/nav/menu）、环形/圆弧/折线/按键图例。
 *
 * 屏幕选择：环境变量 `SIM_DESIGN_SCREEN=main|ride|nav|menu`（默认 main），
 * 也接受 1..4；窗口模式下按 1..4 直接切屏。
 */

#ifndef DESIGN2_COMMON_H
#define DESIGN2_COMMON_H

#include "design_common.h"

#ifdef __cplusplus
extern "C" {
#endif

enum {
    D2_SCREEN_MAIN = 0,  /**< 主界面（每套各自的入口结构） */
    D2_SCREEN_RIDE = 1,  /**< 骑行数据页 */
    D2_SCREEN_NAV = 2,   /**< 导航页 */
    D2_SCREEN_MENU = 3,  /**< 菜单/设置页 */
    D2_SCREEN_COUNT = 4,
};

/** 读 SIM_DESIGN_SCREEN，返回 D2_SCREEN_*。 */
int d2_screen_from_env(void);

/** 建屏 + 注册窗口模式下 1/2/3/4 切屏；打印控件数供 DESIGN.md 用。 */
void d2_scene_start(lv_obj_t *scr, design_build_fn_t build);

/* ── 几何 ──────────────────────────────────────────────────────── */

/** 圆环：以 (cx,cy) 为心、直径 d、描边 thickness 的空心圆。 */
lv_obj_t *d2_ring(lv_obj_t *p, int cx, int cy, int d, int thickness,
                  uint32_t hex);

/** 实心圆。 */
lv_obj_t *d2_disc(lv_obj_t *p, int cx, int cy, int d, uint32_t hex);

/**
 * @brief 圆弧扇段（无旋钮），角度按 LVGL 约定：0=3 点方向、顺时针。
 *
 * start/span 单位度；thickness 为弧线宽度。
 */
lv_obj_t *d2_arc(lv_obj_t *p, int cx, int cy, int d, int thickness,
                 int start, int span, uint32_t hex);

/** 折线（可带圆角端点）。pts 为相对画布的绝对坐标。 */
lv_obj_t *d2_poly(lv_obj_t *p, const lv_point_precise_t *pts, int n,
                  int width, uint32_t hex, bool rounded);

/** 表盘刻度：以 (cx,cy) 为心，角度从 12 点顺时针，r1→r2 的细线。 */
void d2_tick(lv_obj_t *p, int cx, int cy, int deg, int r1, int r2,
             int thickness, uint32_t hex);

/**
 * @brief 底部按键图例（底部区域唯一文案，数字用重色 + 其余灰）。
 *
 * markup 里用 LVGL recolor 语法：`短按 #141518 1# 换卡`。
 * 单行 y 给基线；两行时第二行自动 +16px。
 */
void d2_legend(lv_obj_t *p, int y, int px, uint32_t mute, const char *markup);
void d2_legend2(lv_obj_t *p, int y, int px, uint32_t mute, uint32_t ink,
                const char *l1, const char *l2);

/** 给 markup 里的数字套上 ink 色的便捷宏（编译期字符串拼接，不做转义）。 */
#define D2_KEY(ink_hex, num) "#" ink_hex " " num "#"

#ifdef __cplusplus
}
#endif

#endif /* DESIGN2_COMMON_H */
