{"content": "/**
 * @file design2_common.c
 * @brief WP-DESIGN2/R1：四屏切换 + 圆环/圆弧/折线/刻度/按键图例。
 */

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "design2_common.h"

/* ── 屏幕选择 ──────────────────────────────────────────────────── */

int d2_screen_from_env(void)
{
    const char *s = getenv("SIM_DESIGN_SCREEN");

    if (!s || !s[0]) {
        return D2_SCREEN_MAIN;
    }
    if (strcmp(s, "ride") == 0 || strcmp(s, "1") == 0) {
        return D2_SCREEN_RIDE;
    }
    if (strcmp(s, "nav") == 0 || strcmp(s, "2") == 0) {
        return D2_SCREEN_NAV;
    }
    if (strcmp(s, "menu") == 0 || strcmp(s, "3") == 0) {
        return D2_SCREEN_MENU;
    }
    if (strcmp(s, "main") != 0 && strcmp(s, "0") != 0) {
        fprintf(stderr,
                "sim: unknown SIM_DESIGN_SCREEN=%s (main|ride|nav|menu)\n", s);
    }
    return D2_SCREEN_MAIN;
}

static void (*s_d2_build)(lv_obj_t *, int);
static lv_obj_t *s_d2_scr;

static int d2_count_objs(lv_obj_t *o)
{
    int n = 1;
    const uint32_t c = lv_obj_get_child_count(o);

    for (uint32_t i = 0; i < c; i++) {
        n += d2_count_objs(lv_obj_get_child(o, (int32_t)i));
    }
    return n;
}

static void d2_build_now(int screen)
{
    lv_obj_clean(s_d2_scr);
    s_d2_build(s_d2_scr, screen);
    printf("design2: screen=%d objects=%d\n", screen,
           d2_count_objs(s_d2_scr));
    fflush(stdout);
}

static void d2_key_timer(lv_timer_t *t)
{
    (void)t;
    for (;;) {
        int k = sim_display_take_raw_key();

        if (k == 0) {
            break;
        }
        if (k >= '1' && k <= '4' && s_d2_scr && s_d2_build) {
            d2_build_now(k - '1');
        }
    }
}

void d2_scene_start(lv_obj_t *scr, design_build_fn_t build)
{
    s_d2_scr = scr;
    s_d2_build = build;
    d2_build_now(d2_screen_from_env());
    lv_timer_create(d2_key_timer, 60, NULL);
}

/* ── 几何 ──────────────────────────────────────────────────────── */

lv_obj_t *d2_ring(lv_obj_t *p, int cx, int cy, int d, int thickness,
                  uint32_t hex)
{
    lv_obj_t *o = d_box(p, cx - d / 2, cy - d / 2, d, d, 0x000000u,
                        LV_OPA_TRANSP, d / 2);

    lv_obj_set_style_border_width(o, thickness, 0);
    lv_obj_set_style_border_color(o, lv_color_hex(hex), 0);
    lv_obj_set_style_border_opa(o, LV_OPA_COVER, 0);
    return o;
}

lv_obj_t *d2_disc(lv_obj_t *p, int cx, int cy, int d, uint32_t hex)
{
    return d_box(p, cx - d / 2, cy - d / 2, d, d, hex, LV_OPA_COVER, d / 2);
}

lv_obj_t *d2_arc(lv_obj_t *p, int cx, int cy, int d, int thickness,
                 int start, int span, uint32_t hex)
{
    lv_obj_t *arc = lv_arc_create(p);

    lv_obj_set_size(arc, d, d);
    lv_obj_set_pos(arc, cx - d / 2, cy - d / 2);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_all(arc, 0, 0);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(arc, 0, 0);
    lv_obj_set_style_outline_width(arc, 0, 0);
    lv_obj_set_style_shadow_width(arc, 0, 0);

    /* 主弧不画，只留 indicator 扇段。 */
    lv_obj_set_style_arc_opa(arc, LV_OPA_TRANSP, LV_PART_MAIN);
    lv_obj_set_style_arc_width(arc, 0, LV_PART_MAIN);
    lv_obj_set_style_arc_rounded(arc, false, LV_PART_MAIN);

    lv_obj_set_style_arc_opa(arc, LV_OPA_COVER, LV_PART_INDICATOR);
    lv_obj_set_style_arc_width(arc, thickness, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(arc, lv_color_hex(hex), LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(arc, true, LV_PART_INDICATOR);

    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, LV_PART_KNOB);
    lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
    lv_obj_set_style_pad_all(arc, 0, LV_PART_KNOB);

    lv_arc_set_bg_angles(arc, start, start + span);
    lv_arc_set_rotation(arc, 0);
    lv_arc_set_range(arc, 0, 100);
    lv_arc_set_value(arc, 100);
    return arc;
}

lv_obj_t *d2_poly(lv_obj_t *p, const lv_point_precise_t *pts, int n,
                  int width, uint32_t hex, bool rounded)
{
    lv_obj_t *line = lv_line_create(p);

    lv_obj_remove_style_all(line);
    lv_line_set_points(line, pts, n);
    lv_obj_set_style_line_width(line, width, 0);
    lv_obj_set_style_line_color(line, lv_color_hex(hex), 0);
    lv_obj_set_style_line_opa(line, LV_OPA_COVER, 0);
    lv_obj_set_style_line_rounded(line, rounded, 0);
    lv_obj_remove_flag(line, LV_OBJ_FLAG_CLICKABLE);
    return line;
}

void d2_tick(lv_obj_t *p, int cx, int cy, int deg, int r1, int r2,
             int thickness, uint32_t hex)
{
    const double a = (double)deg * 3.14159265358979 / 180.0;
    const int x1 = cx + (int)lround(sin(a) * r1);
    const int y1 = cy - (int)lround(cos(a) * r1);
    const int x2 = cx + (int)lround(sin(a) * r2);
    const int y2 = cy - (int)lround(cos(a) * r2);

    if (abs(x2 - x1) >= abs(y2 - y1)) {
        d_box(p, x1 < x2 ? x1 : x2, y1, abs(x2 - x1) + 1, thickness, hex,
              LV_OPA_COVER, thickness / 2);
    } else {
        d_box(p, x1, y1 < y2 ? y1 : y2, thickness, abs(y2 - y1) + 1, hex,
              LV_OPA_COVER, thickness / 2);
    }
}

/* ── 按键图例 ──────────────────────────────────────────────────── */

static lv_obj_t *d2_legend_line(lv_obj_t *p, int y, int px, uint32_t mute,
                                const char *markup)
{
    lv_obj_t *l = d_label_w(p, markup, px, mute, 0, y, 240,
                            LV_TEXT_ALIGN_CENTER);

    lv_label_set_recolor(l, true);
    return l;
}

void d2_legend(lv_obj_t *p, int y, int px, uint32_t mute, const char *markup)
{
    (void)d2_legend_line(p, y, px, mute, markup);
}

void d2_legend2(lv_obj_t *p, int y, int px, uint32_t mute, uint32_t ink,
                const char *l1, const char *l2)
{
    char buf[96];

    /* 调用方传纯文本；这里不注入颜色，保持 ink 参数给未用（签名对齐）。 */
    (void)ink;
    snprintf(buf, sizeof(buf), "%s", l1);
    (void)d2_legend_line(p, y, px, mute, buf);
    snprintf(buf, sizeof(buf), "%s", l2);
    (void)d2_legend_line(p, y + px + 6, px, mute, buf);
}
