{"content": "/**
 * @file scene_design_d.c
 * @brief WP-DESIGN2 方案 D「轮转卡片 Carousel」。
 *
 * 主界面 = 横向模式卡轮转（骑行/导航/记录/设置）：选中卡放大居中、
 * 两侧各露 24px 邻卡边并带邻卡序号；底部页点 + 两行按键图例。
 * 四屏由 SIM_DESIGN_SCREEN=main|ride|nav|menu 选（见 design2_common.h）。
 *
 * 识别性元素：卡片本身（大圆角白卡 + 邻卡露边 + 序号），
 * 以及"无胶囊、无边框图标"的排版：所有强调色只出现在形状上。
 */

#include <math.h>

#include "design2_common.h"

/* ── 色板（工作室纸白 / 单一电光蓝）────────────────────────────── */
#define D_BG     0xECE9E2u   /**< 纸底 */
#define D_CARD   0xFFFFFFu   /**< 居中卡 */
#define D_PEEK   0xE2DFD7u   /**< 邻卡（无描边、无投影） */
#define D_INK    0x141518u   /**< 主文字（近黑） */
#define D_MUTE   0x87837Bu   /**< 次要文字 */
#define D_DIM    0xB4AFA6u   /**< 邻卡序号 */
#define D_ACC    0x2A54FFu   /**< 唯一强调色 */
#define D_TRACK  0xD8D4CBu   /**< 轨道/刻度 */

#define D_INK_S  "141518"

static void d_hair(lv_obj_t *p, int x, int y, int w)
{
    d_hline(p, x, y, w, 0x000000u, 24);
}

/** 几何符号：0 车轮 / 1 波形 / 2 路线 / 3 齿轮（全用基本形，0 位图）。 */
static void d_glyph(lv_obj_t *p, int cx, int cy, int kind, uint32_t ink,
                    uint32_t acc)
{
    switch (kind) {
        case 0:
            d2_ring(p, cx, cy, 56, 3, ink);
            d2_ring(p, cx, cy, 22, 3, ink);
            d_box(p, cx - 1, cy - 28, 3, 9, ink, LV_OPA_COVER, 1);
            d_box(p, cx - 1, cy + 20, 3, 9, ink, LV_OPA_COVER, 1);
            d_box(p, cx - 28, cy - 1, 9, 3, ink, LV_OPA_COVER, 1);
            d_box(p, cx + 20, cy - 1, 9, 3, ink, LV_OPA_COVER, 1);
            d2_disc(p, cx, cy, 6, acc);
            break;
        case 1: {
            static lv_point_precise_t w[5];
            w[0].x = cx - 28; w[0].y = cy + 8;
            w[1].x = cx - 14; w[1].y = cy - 14;
            w[2].x = cx;      w[2].y = cy + 4;
            w[3].x = cx + 14; w[3].y = cy - 16;
            w[4].x = cx + 28; w[4].y = cy + 2;
            (void)d2_poly(p, w, 5, 3, ink, true);
            d2_disc(p, cx - 28, cy + 8, 8, acc);
            break;
        }
        case 2: {
            static lv_point_precise_t r[3];
            r[0].x = cx - 24; r[0].y = cy + 20;
            r[1].x = cx - 2;  r[1].y = cy - 2;
            r[2].x = cx + 22; r[2].y = cy - 22;
            (void)d2_poly(p, r, 3, 2, ink, true);
            d2_disc(p, cx - 24, cy + 20, 9, ink);
            d2_disc(p, cx - 2, cy - 2, 9, ink);
            d2_disc(p, cx + 22, cy - 22, 11, acc);
            break;
        }
        default: {
            d2_ring(p, cx, cy, 26, 4, ink);
            for (int i = 0; i < 8; i++) {
                const double a = (double)i * 45.0 * 3.14159265 / 180.0;
                const int x = cx + (int)lround(sin(a) * 21.0) - 3;
                const int y = cy - (int)lround(cos(a) * 21.0) - 3;
                d_box(p, x, y, 6, 6, ink, LV_OPA_COVER, 1);
            }
            d2_disc(p, cx, cy, 7, acc);
            break;
        }
    }
}

/** 底部按键图例：底部横线 + 一行/两行。 */
static void d_keys(lv_obj_t *p, const char *l1, const char *l2)
{
    d_hair(p, 0, 288, 240);
    if (!l2) {
        d2_legend(p, 300, 10, D_MUTE, l1);
    } else {
        d2_legend(p, 292, 9, D_MUTE, l1);
        d2_legend(p, 305, 9, D_MUTE, l2);
    }
}

/* ── 1. 主界面：轮转卡片 ───────────────────────────────────────── */

typedef struct {
    const char *name;
    const char *sub;
    int glyph;
} d_card_t;

static const d_card_t d_cards[4] = {
    { "骑行", "实时数据 · 开始骑行", 0 },
    { "导航", "路线 · 转向提示", 1 },
    { "记录", "历史 · 数据回顾", 2 },
    { "设置", "设备 · 显示 · 关于", 3 },
};

/** 邻卡：只露出 24px 边 + 自身序号，不画图标（避免边缘噪声）。 */
static void d_peek(lv_obj_t *scr, int side, int idx)
{
    if (side < 0) {
        d_box(scr, -110, 72, 134, 160, D_PEEK, LV_OPA_COVER, 28);
        d_label_w(scr, d_cards[idx].name[0] == 0 ? "" : "04", 20, D_DIM,
                  0, 126, 24, LV_TEXT_ALIGN_CENTER);
    } else {
        d_box(scr, 216, 72, 134, 160, D_PEEK, LV_OPA_COVER, 28);
        d_label_w(scr, "02", 20, D_DIM, 217, 126, 23, LV_TEXT_ALIGN_CENTER);
    }
}

static void d_main(lv_obj_t *scr)
{
    d_bg(scr, D_BG);

    d_label(scr, "模式", 11, D_MUTE, 24, 17);
    d_label_w(scr, "01 / 04", 11, D_MUTE, 140, 17, 76, LV_TEXT_ALIGN_RIGHT);

    d_peek(scr, -1, 3);
    d_peek(scr, 1, 1);

    d_box(scr, 40, 56, 160, 192, D_CARD, LV_OPA_COVER, 28);
    d_label(scr, "01", 12, D_ACC, 64, 72);
    d_glyph(scr, 120, 120, d_cards[0].glyph, D_INK, D_ACC);
    d_label_w(scr, d_cards[0].name, 30, D_INK, 40, 158, 160,
              LV_TEXT_ALIGN_CENTER);
    d_hair(scr, 72, 204, 96);
    d_label_w(scr, d_cards[0].sub, 10, D_MUTE, 40, 212, 160,
              LV_TEXT_ALIGN_CENTER);

    /* 页点：当前 = 20x6 药丸，其余 6x6 圆点。 */
    d_box(scr, 89, 259, 20, 6, D_ACC, LV_OPA_COVER, 3);
    d_dot(scr, 117, 259, 6, D_DIM);
    d_dot(scr, 131, 259, 6, D_DIM);
    d_dot(scr, 145, 259, 6, D_DIM);

    d_keys(scr,
           "短按 #" D_INK_S " 1# 换卡 · 长按 #" D_INK_S " 1# 进入",
           "短按 #" D_INK_S " 2# 上一张 · 长按 #" D_INK_S " 2# 开始");
}

/* ── 2. 骑行数据页 ─────────────────────────────────────────────── */

static void d_metric(lv_obj_t *scr, int x, int y, const char *label,
                     const char *val, const char *unit)
{
    d_label(scr, label, 9, D_MUTE, x, y);
    lv_obj_t *row = d_stack(scr, x, y + 9, 92, 28, LV_FLEX_ALIGN_START, 3);
    lv_obj_t *v = lv_label_create(row);

    lv_label_set_text(v, val);
    lv_obj_set_style_text_font(v, sim_font_cjk(20), 0);
    lv_obj_set_style_text_color(v, lv_color_hex(D_INK), 0);
    if (unit && unit[0]) {
        lv_obj_t *u = lv_label_create(row);

        lv_label_set_text(u, unit);
        lv_obj_set_style_text_font(u, sim_font_cjk(9), 0);
        lv_obj_set_style_text_color(u, lv_color_hex(D_MUTE), 0);
        lv_obj_set_style_pad_bottom(u, 3, 0);
    }
}

static void d_ride(lv_obj_t *scr)
{
    d_bg(scr, D_BG);

    d_label(scr, "骑行中", 11, D_MUTE, 24, 17);
    d_label_w(scr, "00:42:18", 11, D_INK, 140, 17, 76, LV_TEXT_ALIGN_RIGHT);

    lv_obj_t *srow = d_stack(scr, 22, 30, 160, 100, LV_FLEX_ALIGN_START, 0);
    lv_obj_t *spd = lv_label_create(srow);

    lv_label_set_text(spd, "24.8");
    lv_obj_set_style_text_font(spd, sim_font_cjk(80), 0);
    lv_obj_set_style_text_color(spd, lv_color_hex(D_INK), 0);
    lv_obj_set_style_text_letter_space(spd, -1, 0);
    d_label(scr, "km/h", 11, D_MUTE, 182, 112);

    /* 速度区间：轨道 + 42% 强调填充，刻度只画 1px。 */
    d_box(scr, 24, 146, 192, 4, D_TRACK, LV_OPA_COVER, 2);
    d_box(scr, 24, 146, 80, 4, D_ACC, LV_OPA_COVER, 2);
    for (int i = 1; i < 4; i++) {
        d_vline(scr, 24 + i * 48, 151, 4, 0x000000u, 40);
    }
    d_label(scr, "0", 9, D_MUTE, 24, 158);
    d_label_w(scr, "30", 9, D_MUTE, 84, 158, 80, LV_TEXT_ALIGN_CENTER);
    d_label_w(scr, "60 km/h", 9, D_MUTE, 156, 158, 60, LV_TEXT_ALIGN_RIGHT);

    d_hair(scr, 24, 184, 192);

    d_metric(scr, 24, 194, "里程", "12.4", "km");
    d_metric(scr, 128, 194, "心率", "142", "bpm");
    d_hair(scr, 24, 236, 192);
    d_metric(scr, 24, 246, "踏频", "86", "rpm");
    d_metric(scr, 128, 246, "海拔", "326", "m");

    d_keys(scr, "短按 #" D_INK_S " 1# 切页 · 长按 #" D_INK_S " 2# 结束",
           NULL);
}

/* ── 3. 导航页 ─────────────────────────────────────────────────── */

static void d_nav(lv_obj_t *scr)
{
    d_bg(scr, D_BG);

    d_label(scr, "导航", 11, D_MUTE, 24, 17);
    d_label_w(scr, "剩余 8.4 km", 11, D_INK, 120, 17, 96, LV_TEXT_ALIGN_RIGHT);

    /* 地图占位：纸地图 + 白路 + 单一强调色路线（不渲染 vmap）。 */
    d_box(scr, 24, 44, 192, 180, 0xE6E2DAu, LV_OPA_COVER, 20);
    d_box(scr, 24, 106, 192, 3, 0xFBF9F4u, LV_OPA_COVER, 0);
    d_box(scr, 104, 44, 3, 180, 0xFBF9F4u, LV_OPA_COVER, 0);
    {
        static lv_point_precise_t road[3] = {
            { 24, 196 }, { 104, 132 }, { 216, 168 },
        };
        (void)d2_poly(scr, road, 3, 3, 0xFBF9F4u, true);
    }
    {
        static lv_point_precise_t rt[6] = {
            { 60, 208 }, { 60, 152 }, { 104, 152 }, { 104, 96 }, { 152, 96 },
            { 152, 60 },
        };
        (void)d2_poly(scr, rt, 6, 4, D_ACC, true);
    }
    d2_disc(scr, 60, 208, 10, D_INK);
    d2_disc(scr, 152, 60, 16, D_INK);
    d2_disc(scr, 152, 60, 8, D_CARD);

    /* 转向条：箭头 + 距离 + 动作。 */
    {
        static lv_point_precise_t shaft[3] = { { 36, 276 }, { 36, 250 }, { 54, 250 } };
        static lv_point_precise_t head[3] = { { 48, 243 }, { 57, 250 }, { 48, 257 } };
        (void)d2_poly(scr, shaft, 3, 4, D_ACC, true);
        (void)d2_poly(scr, head, 3, 4, D_ACC, true);
    }
    d_label(scr, "300 m", 22, D_INK, 68, 236);
    d_label(scr, "右转 · 进入学院路", 10, D_MUTE, 68, 264);

    d_keys(scr, "短按 #" D_INK_S " 1# 切页 · 长按 #" D_INK_S " 2# 结束",
           NULL);
}

/* ── 4. 菜单/设置页 ────────────────────────────────────────────── */

typedef struct {
    const char *name;
    const char *value;
} d_row_t;

static const d_row_t d_rows[4] = {
    { "显示", "自动" },
    { "传感器", "3 个" },
    { "声音", "开" },
    { "关于", "v1.2.6" },
};

static void d_menu(lv_obj_t *scr)
{
    d_bg(scr, D_BG);

    d_label(scr, "设置", 28, D_INK, 24, 12);
    d_label_w(scr, "4 项", 11, D_MUTE, 140, 26, 76, LV_TEXT_ALIGN_RIGHT);

    d_box(scr, 24, 64, 192, 176, D_CARD, LV_OPA_COVER, 20);

    for (int i = 0; i < 4; i++) {
        const int y = 72 + i * 40;
        const bool on = (i == 0);

        if (on) {
            d_box(scr, 28, y + 10, 4, 20, D_ACC, LV_OPA_COVER, 2);
        }
        d_label(scr, d_rows[i].name, on ? 16 : 14, on ? D_INK : D_MUTE,
                48, y + (on ? 8 : 10));
        d_label_w(scr, d_rows[i].value, 10, D_MUTE, 140, y + 14, 52,
                  LV_TEXT_ALIGN_RIGHT);
        d_chevron(scr, 200, y + 15, on ? D_ACC : D_DIM, 8);
        if (i < 3) {
            d_hair(scr, 48, y + 40, 152);
        }
    }

    d_label(scr, "固件 v1.2.6 · 电量 86%", 10, D_MUTE, 24, 258);

    d_keys(scr,
           "短按 #" D_INK_S " 1# 下一项 · 长按 #" D_INK_S " 1# 进入",
           "短按 #" D_INK_S " 2# 返回");
}

/* ── 场景入口 ──────────────────────────────────────────────────── */

static void design_d_build(lv_obj_t *scr, int screen)
{
    switch (screen) {
        case D2_SCREEN_RIDE: d_ride(scr); break;
        case D2_SCREEN_NAV: d_nav(scr); break;
        case D2_SCREEN_MENU: d_menu(scr); break;
        default: d_main(scr); break;
    }
}

void scene_design_d_create(lv_obj_t *scr, const sim_cfg_t *cfg)
{
    (void)cfg;
    d2_scene_start(scr, design_d_build);
}
