{"content": "/**
 * @file scene_design_e.c
 * @brief WP-DESIGN2 方案 E「模式盘 Dial」。
 *
 * 主界面 = 表冠式圆盘：可见整圈轨道 + 一段强调色扇区指向当前模式，
 * 4 个模式名沿圆周分布在 12/3/6/9 点；盘心 = 模式名 + 一句描述 + 关键数字。
 * 子页沿用同一套"圆"语言：骑行页是 270° 仪表弧、导航页是圆形地图。
 *
 * 四屏由 SIM_DESIGN_SCREEN=main|ride|nav|menu 选（见 design2_common.h）。
 */

#include <math.h>

#include "design2_common.h"

/* ── 色板（宣纸白 / 单一墨绿）──────────────────────────────────── */
#define E_BG     0xF7F5F0u   /**< 纸底 */
#define E_INK    0x141518u   /**< 主文字 */
#define E_MUTE   0x8B8781u   /**< 次要文字 */
#define E_ACC    0x0B6E4Fu   /**< 唯一强调色（墨绿） */
#define E_TRACK  0xE2DDD3u   /**< 轨道 */
#define E_TICK   0xC8C3B8u   /**< 刻度 */
#define E_MAP    0xE9E6DFu   /**< 地图纸 */
#define E_ROAD   0xFBF9F4u   /**< 地图道路 */

#define E_INK_S  "141518"

static void e_hair(lv_obj_t *p, int x, int y, int w)
{
    d_hline(p, x, y, w, 0x000000u, 24);
}

/** 270° 仪表弧（起点左下、终点右下），返回 arc 以便复用。 */
static lv_obj_t *e_gauge(lv_obj_t *scr, int cx, int cy, int d, int pct)
{
    lv_obj_t *arc = lv_arc_create(scr);

    lv_obj_set_size(arc, d, d);
    lv_obj_set_pos(arc, cx - d / 2, cy - d / 2);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_remove_flag(arc, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_style_pad_all(arc, 0, 0);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, 0);
    lv_obj_set_style_border_width(arc, 0, 0);
    lv_obj_set_style_outline_width(arc, 0, 0);
    lv_obj_set_style_shadow_width(arc, 0, 0);
    lv_obj_set_style_arc_width(arc, 8, LV_PART_MAIN);
    lv_obj_set_style_arc_color(arc, lv_color_hex(E_TRACK), LV_PART_MAIN);
    lv_obj_set_style_arc_rounded(arc, true, LV_PART_MAIN);
    lv_obj_set_style_arc_width(arc, 8, LV_PART_INDICATOR);
    lv_obj_set_style_arc_color(arc, lv_color_hex(E_ACC), LV_PART_INDICATOR);
    lv_obj_set_style_arc_rounded(arc, true, LV_PART_INDICATOR);
    lv_obj_set_style_bg_opa(arc, LV_OPA_TRANSP, LV_PART_KNOB);
    lv_obj_set_style_border_width(arc, 0, LV_PART_KNOB);
    lv_obj_set_style_pad_all(arc, 0, LV_PART_KNOB);
    lv_arc_set_bg_angles(arc, 0, 270);
    lv_arc_set_rotation(arc, 135);
    lv_arc_set_range(arc, 0, 100);
    lv_arc_set_value(arc, pct);
    return arc;
}

/* ── 1. 主界面：模式盘 ─────────────────────────────────────────── */

typedef struct {
    const char *name;
    const char *desc;
    const char *value;
    const char *unit;
} e_mode_t;

static const e_mode_t e_modes[4] = {
    { "骑行", "实时数据 · 开始骑行", "42.6", "km 上次" },
    { "导航", "路线 · 转向提示", "8.4", "km 剩余" },
    { "记录", "历史 · 数据回顾", "68", "km 本周" },
    { "设置", "设备 · 显示 · 关于", "86", "% 电量" },
};

static void e_mode_label(lv_obj_t *scr, int idx, int x, int y, bool on)
{
    d_label_w(scr, e_modes[idx].name, on ? 13 : 11,
              on ? E_INK : E_MUTE, x - 20, y - 9, 40, LV_TEXT_ALIGN_CENTER);
}

static void e_main(lv_obj_t *scr)
{
    d_bg(scr, E_BG);

    d_label(scr, "模式", 11, E_MUTE, 24, 17);
    d_label_w(scr, "01 / 04", 11, E_MUTE, 140, 17, 76, LV_TEXT_ALIGN_RIGHT);

    /* 表盘：整圈轨道 + 52° 强调扇区 + 12 格刻度。 */
    d2_ring(scr, 120, 150, 160, 2, E_TRACK);
    (void)d2_arc(scr, 120, 150, 160, 6, 244, 52, E_ACC);

    for (int i = 0; i < 12; i++) {
        const int deg = i * 30;
        const bool major = (i % 3 == 0);

        d2_tick(scr, 120, 150, deg, major ? 64 : 70, 76,
                major ? 3 : 1, major ? E_INK : E_TICK);
    }

    e_mode_label(scr, 0, 120, 50, true);
    e_mode_label(scr, 1, 220, 150, false);
    e_mode_label(scr, 2, 120, 250, false);
    e_mode_label(scr, 3, 20, 150, false);

    /* 盘心：模式名 / 描述 / 关键数字。 */
    d_label_w(scr, e_modes[0].name, 30, E_INK, 40, 112, 160,
              LV_TEXT_ALIGN_CENTER);
    d_label_w(scr, e_modes[0].desc, 10, E_MUTE, 40, 152, 160,
              LV_TEXT_ALIGN_CENTER);
    e_hair(scr, 100, 172, 40);
    d_label_w(scr, "上次骑行", 9, E_MUTE, 40, 178, 160, LV_TEXT_ALIGN_CENTER);

    {
        lv_obj_t *row = d_stack(scr, 60, 188, 120, 26, LV_FLEX_ALIGN_CENTER, 4);
        lv_obj_t *v = lv_label_create(row);

        lv_label_set_text(v, e_modes[0].value);
        lv_obj_set_style_text_font(v, sim_font_cjk(22), 0);
        lv_obj_set_style_text_color(v, lv_color_hex(E_INK), 0);
        lv_obj_t *u = lv_label_create(row);

        lv_label_set_text(u, e_modes[0].unit);
        lv_obj_set_style_text_font(u, sim_font_cjk(9), 0);
        lv_obj_set_style_text_color(u, lv_color_hex(E_MUTE), 0);
        lv_obj_set_style_pad_bottom(u, 3, 0);
    }

    d2_legend(scr, 274, 9, E_MUTE,
              "短按 #" E_INK_S " 1# 旋转 · 长按 #" E_INK_S " 1# 进入");
    d2_legend(scr, 289, 9, E_MUTE,
              "短按 #" E_INK_S " 2# 上一项 · 长按 #" E_INK_S " 2# 开始");
}

/* ── 2. 骑行数据页 ─────────────────────────────────────────────── */

typedef struct {
    const char *label;
    const char *value;
    const char *unit;
} e_cell_t;

static void e_cell(lv_obj_t *scr, int cx, int y, const e_cell_t *c, int px)
{
    d_label_w(scr, c->value, px, E_INK, cx - 32, y, 64, LV_TEXT_ALIGN_CENTER);
    {
        char buf[24];

        if (c->unit && c->unit[0]) {
            snprintf(buf, sizeof(buf), "%s", c->unit);
            d_label_w(scr, buf, 9, E_MUTE, cx - 32, y + px + 3, 64,
                      LV_TEXT_ALIGN_CENTER);
        }
    }
    d_label_w(scr, c->label, 9, E_MUTE, cx - 32, y + px + 15, 64,
              LV_TEXT_ALIGN_CENTER);
}

static void e_ride(lv_obj_t *scr)
{
    static const e_cell_t top[3] = {
        { "里程", "12.4", "km" },
        { "时间", "0:42", "" },
        { "心率", "142", "bpm" },
    };
    static const e_cell_t bot[3] = {
        { "踏频", "86", "rpm" },
        { "海拔", "326", "m" },
        { "坡度", "3.2", "%" },
    };

    d_bg(scr, E_BG);

    d_label(scr, "骑行中", 11, E_MUTE, 24, 17);
    d_label_w(scr, "GPS 12", 11, E_MUTE, 140, 17, 76, LV_TEXT_ALIGN_RIGHT);

    (void)e_gauge(scr, 120, 124, 176, 42);
    d_label_w(scr, "24.8", 56, E_INK, 40, 96, 160, LV_TEXT_ALIGN_CENTER);
    d_label_w(scr, "km/h", 11, E_MUTE, 40, 164, 160, LV_TEXT_ALIGN_CENTER);

    e_cell(scr, 56, 210, &top[0], 18);
    e_cell(scr, 120, 210, &top[1], 18);
    e_cell(scr, 184, 210, &top[2], 18);

    e_hair(scr, 24, 246, 192);

    e_cell(scr, 56, 254, &bot[0], 18);
    e_cell(scr, 120, 254, &bot[1], 18);
    e_cell(scr, 184, 254, &bot[2], 18);

    d2_legend(scr, 300, 10, E_MUTE,
              "短按 #" E_INK_S " 1# 切页 · 长按 #" E_INK_S " 2# 结束");
}

/* ── 3. 导航页（圆形地图）─────────────────────────────────────── */

static void e_nav(lv_obj_t *scr)
{
    d_bg(scr, E_BG);

    d_label(scr, "导航", 11, E_MUTE, 24, 17);
    d_label_w(scr, "剩余 8.4 km", 11, E_INK, 120, 17, 96, LV_TEXT_ALIGN_RIGHT);

    d2_disc(scr, 120, 148, 184, E_MAP);
    d2_ring(scr, 120, 148, 184, 1, 0xDCD7CCu);

    /* 道路：只留 3px 白线，路网不抢路线。 */
    d_box(scr, 28, 118, 184, 3, E_ROAD, LV_OPA_COVER, 0);
    d_box(scr, 96, 56, 3, 184, E_ROAD, LV_OPA_COVER, 0);
    {
        static lv_point_precise_t road[2] = { { 40, 224 }, { 196, 84 } };
        (void)d2_poly(scr, road, 2, 3, E_ROAD, true);
    }
    {
        static lv_point_precise_t rt[6] = {
            { 72, 212 }, { 72, 170 }, { 96, 170 }, { 96, 118 }, { 140, 118 },
            { 140, 84 },
        };
        (void)d2_poly(scr, rt, 6, 4, E_ACC, true);
    }

    /* 当前位置：黑点 + 强调色光环；终点：黑环白心。 */
    d2_ring(scr, 72, 208, 18, 2, E_ACC);
    d2_disc(scr, 72, 208, 8, E_INK);
    d2_disc(scr, 140, 84, 16, E_INK);
    d2_disc(scr, 140, 84, 8, E_ROAD);

    d_label_w(scr, "N", 9, E_MUTE, 110, 58, 20, LV_TEXT_ALIGN_CENTER);

    {
        static lv_point_precise_t shaft[3] = { { 40, 284 }, { 40, 258 }, { 56, 258 } };
        static lv_point_precise_t head[3] = { { 51, 252 }, { 59, 258 }, { 51, 264 } };
        (void)d2_poly(scr, shaft, 3, 4, E_ACC, true);
        (void)d2_poly(scr, head, 3, 4, E_ACC, true);
    }
    d_label(scr, "300 m", 22, E_INK, 70, 248);
    d_label(scr, "右转 · 进入学院路", 10, E_MUTE, 70, 274);

    d2_legend(scr, 300, 10, E_MUTE,
              "短按 #" E_INK_S " 1# 切页 · 长按 #" E_INK_S " 2# 结束");
}

/* ── 4. 菜单/设置页 ────────────────────────────────────────────── */

typedef struct {
    const char *name;
    const char *value;
} e_row_t;

static const e_row_t e_rows[4] = {
    { "显示", "自动" },
    { "传感器", "3 个" },
    { "声音", "开" },
    { "关于", "v1.2.6" },
};

static void e_menu(lv_obj_t *scr)
{
    d_bg(scr, E_BG);

    d_label(scr, "设置", 26, E_INK, 24, 14);
    d_label_w(scr, "4 项", 10, E_MUTE, 140, 26, 76, LV_TEXT_ALIGN_RIGHT);

    for (int i = 0; i < 4; i++) {
        const int y = 64 + i * 44;
        const bool on = (i == 0);

        /* 指针：选中行用短强调色竖条，替代卡片/边框。 */
        d_box(scr, 24, y + 12, on ? 3 : 1, on ? 20 : 20,
              on ? E_ACC : E_TICK, LV_OPA_COVER, 1);
        d_label(scr, e_rows[i].name, on ? 18 : 14, on ? E_INK : E_MUTE,
                40, y + (on ? 8 : 12));
        d_label_w(scr, e_rows[i].value, 10, E_MUTE, 140, y + 16, 52,
                  LV_TEXT_ALIGN_RIGHT);
        if (on) {
            d_chevron(scr, 200, y + 16, E_ACC, 8);
        }
        if (i < 3) {
            e_hair(scr, 40, y + 44, 176);
        }
    }

    d_label(scr, "固件 v1.2.6 · 电量 86%", 10, E_MUTE, 24, 258);

    d2_legend(scr, 276, 9, E_MUTE,
              "短按 #" E_INK_S " 1# 下一项 · 长按 #" E_INK_S " 1# 进入");
    d2_legend(scr, 291, 9, E_MUTE, "短按 #" E_INK_S " 2# 返回");
}

/* ── 场景入口 ──────────────────────────────────────────────────── */

static void design_e_build(lv_obj_t *scr, int screen)
{
    switch (screen) {
        case D2_SCREEN_RIDE: e_ride(scr); break;
        case D2_SCREEN_NAV: e_nav(scr); break;
        case D2_SCREEN_MENU: e_menu(scr); break;
        default: e_main(scr); break;
    }
}

void scene_design_e_create(lv_obj_t *scr, const sim_cfg_t *cfg)
{
    (void)cfg;
    d2_scene_start(scr, design_e_build);
}
