{"content": "/**
 * @file scene_design_f.c
 * @brief WP-DESIGN2 方案 F「Hero + Dock」。
 *
 * 主界面 = 上方通栏 Hero（上次骑行：96px 主数字 + 三项小指标 + 开始骑行 CTA），
 * 下方一条 4 格 Dock（骑行/导航/记录/设置），选中格顶部一条强调色短杠；
 * 按键在 Dock 上左右移动，Hero 随选中项换内容（静态稿画第 1 格）。
 * 子页沿用"大数字压顶 + 通栏表格式清单"的编辑排版。
 *
 * 四屏由 SIM_DESIGN_SCREEN=main|ride|nav|menu 选（见 design2_common.h）。
 */

#include <math.h>

#include "design2_common.h"

/* ── 色板（牛皮纸底 / 单一酒红）────────────────────────────────── */
#define F_BG     0xE9E5DDu   /**< 纸底（Dock 区） */
#define F_CARD   0xFFFFFFu   /**< Hero 通栏 */
#define F_INK    0x111214u   /**< 主文字 */
#define F_MUTE   0x87827Au   /**< 次要文字 */
#define F_ACC    0x8C1D40u   /**< 唯一强调色（酒红） */
#define F_TRACK  0xD9D3C8u   /**< 轨道 / 未选图标 */
#define F_MAP    0xE6E2D9u   /**< 地图纸 */
#define F_ROAD   0xFBF9F4u   /**< 道路 */

#define F_INK_S  "111214"

static void f_hair(lv_obj_t *p, int x, int y, int w)
{
    d_hline(p, x, y, w, 0x000000u, 24);
}

/** 左对齐重色图例（Hero CTA 用；数字深色、其余灰）。 */
static void f_cta(lv_obj_t *p, int x, int y, const char *markup)
{
    lv_obj_t *l = d_label(p, markup, 11, F_MUTE, x, y);

    lv_label_set_recolor(l, true);
}

/** Dock 符号：0 车轮 / 1 罗盘 / 2 记录条 / 3 齿轮。 */
static void f_icon(lv_obj_t *p, int cx, int cy, int kind, uint32_t color)
{
    switch (kind) {
        case 0:
            d2_ring(p, cx, cy, 22, 2, color);
            d2_disc(p, cx, cy, 5, color);
            break;
        case 1: {
            static lv_point_precise_t up[3];
            up[0].x = cx - 8; up[0].y = cy + 7;
            up[1].x = cx;     up[1].y = cy - 8;
            up[2].x = cx + 8; up[2].y = cy + 7;
            (void)d2_poly(p, up, 3, 2, color, true);
            d_box(p, cx - 1, cy - 1, 2, 9, color, LV_OPA_COVER, 1);
            break;
        }
        case 2:
            d_box(p, cx - 9, cy - 6, 18, 2, color, LV_OPA_COVER, 1);
            d_box(p, cx - 9, cy, 14, 2, color, LV_OPA_COVER, 1);
            d_box(p, cx - 9, cy + 6, 9, 2, color, LV_OPA_COVER, 1);
            break;
        default:
            d2_ring(p, cx, cy, 16, 2, color);
            for (int i = 0; i < 8; i++) {
                const double a = (double)i * 45.0 * 3.14159265 / 180.0;
                const int x = cx + (int)lround(sin(a) * 10.0) - 1;
                const int y = cy - (int)lround(cos(a) * 10.0) - 1;
                d_box(p, x, y, 3, 3, color, LV_OPA_COVER, 1);
            }
            d2_disc(p, cx, cy, 4, color);
            break;
    }
}

/* ── 1. 主界面：Hero + Dock ────────────────────────────────────── */

typedef struct {
    const char *name;
    int icon;
} f_dock_t;

static const f_dock_t f_dock[4] = {
    { "骑行", 0 }, { "导航", 1 }, { "记录", 2 }, { "设置", 3 },
};

static void f_stat(lv_obj_t *scr, int x, const char *val, const char *unit,
                   const char *label)
{
    lv_obj_t *row = d_stack(scr, x, 158, 72, 22, LV_FLEX_ALIGN_START, 2);
    lv_obj_t *v = lv_label_create(row);

    lv_label_set_text(v, val);
    lv_obj_set_style_text_font(v, sim_font_cjk(16), 0);
    lv_obj_set_style_text_color(v, lv_color_hex(F_INK), 0);
    if (unit && unit[0]) {
        lv_obj_t *u = lv_label_create(row);

        lv_label_set_text(u, unit);
        lv_obj_set_style_text_font(u, sim_font_cjk(9), 0);
        lv_obj_set_style_text_color(u, lv_color_hex(F_MUTE), 0);
        lv_obj_set_style_pad_bottom(u, 2, 0);
    }
    d_label(scr, label, 9, F_MUTE, x, 181);
}

static void f_main(lv_obj_t *scr)
{
    d_bg(scr, F_BG);

    /* Hero 通栏白底（无圆角、无投影、无描边）。 */
    d_box(scr, 0, 0, 240, 232, F_CARD, LV_OPA_COVER, 0);

    d_label(scr, "上次骑行", 11, F_MUTE, 24, 16);
    d_label_w(scr, "10月28日 · 周三", 11, F_MUTE, 112, 16, 104,
              LV_TEXT_ALIGN_RIGHT);

    {
        lv_obj_t *srow = d_stack(scr, 20, 28, 190, 112, LV_FLEX_ALIGN_START, 0);
        lv_obj_t *big = lv_label_create(srow);

        lv_label_set_text(big, "42.6");
        lv_obj_set_style_text_font(big, sim_font_cjk(88), 0);
        lv_obj_set_style_text_color(big, lv_color_hex(F_INK), 0);
        lv_obj_set_style_text_letter_space(big, -1, 0);
    }
    d_label(scr, "km", 12, F_MUTE, 198, 116);

    f_hair(scr, 24, 150, 192);

    f_stat(scr, 24, "1:52", "", "用时");
    f_stat(scr, 96, "26.4", "km/h", "均速");
    f_stat(scr, 168, "326", "m", "爬升");

    d_box(scr, 24, 206, 3, 16, F_ACC, LV_OPA_COVER, 1);
    f_cta(scr, 36, 205, "长按 #" F_INK_S " 2# 开始骑行");

    /* Dock：4 格等分，选中格顶部一条 40px 强调色短杠。 */
    f_hair(scr, 0, 232, 240);
    d_box(scr, 10, 230, 40, 3, F_ACC, LV_OPA_COVER, 1);

    for (int i = 0; i < 4; i++) {
        const int cx = 30 + i * 60;
        const bool on = (i == 0);

        f_icon(scr, cx, 252, f_dock[i].icon, on ? F_INK : F_TRACK);
        d_label_w(scr, f_dock[i].name, 9, on ? F_INK : F_MUTE, cx - 30, 275,
                  60, LV_TEXT_ALIGN_CENTER);
    }

    d2_legend(scr, 302, 9, F_MUTE,
              "短按 #" F_INK_S " 1# 选择 · 长按 #" F_INK_S " 1# 进入 · 短按 #"
              F_INK_S " 2# 上一项");
}

/* ── 2. 骑行数据页 ─────────────────────────────────────────────── */

typedef struct {
    const char *label;
    const char *value;
    const char *unit;
} f_row_t;

static const f_row_t f_rows[4] = {
    { "里程", "12.4", "km" },
    { "心率", "142", "bpm" },
    { "踏频", "86", "rpm" },
    { "海拔", "326", "m" },
};

static void f_ride(lv_obj_t *scr)
{
    d_bg(scr, F_BG);

    d_box(scr, 0, 0, 240, 188, F_CARD, LV_OPA_COVER, 0);

    d_label(scr, "骑行中", 11, F_MUTE, 24, 16);
    d_label_w(scr, "00:42:18", 11, F_INK, 132, 16, 84, LV_TEXT_ALIGN_RIGHT);

    {
        lv_obj_t *srow = d_stack(scr, 20, 26, 190, 110, LV_FLEX_ALIGN_START, 0);
        lv_obj_t *big = lv_label_create(srow);

        lv_label_set_text(big, "24.8");
        lv_obj_set_style_text_font(big, sim_font_cjk(88), 0);
        lv_obj_set_style_text_color(big, lv_color_hex(F_INK), 0);
        lv_obj_set_style_text_letter_space(big, -1, 0);
    }
    d_label(scr, "km/h", 12, F_MUTE, 196, 112);

    d_box(scr, 24, 154, 192, 4, F_TRACK, LV_OPA_COVER, 2);
    d_box(scr, 24, 154, 80, 4, F_ACC, LV_OPA_COVER, 2);
    d_label(scr, "0", 9, F_MUTE, 24, 164);
    d_label_w(scr, "30", 9, F_MUTE, 84, 164, 80, LV_TEXT_ALIGN_CENTER);
    d_label_w(scr, "60 km/h", 9, F_MUTE, 156, 164, 60, LV_TEXT_ALIGN_RIGHT);

    for (int i = 0; i < 4; i++) {
        const int y = 188 + i * 23;

        d_label(scr, f_rows[i].label, 10, F_MUTE, 24, y + 4);
        {
            lv_obj_t *row = d_stack(scr, 120, y + 1, 96, 20,
                                    LV_FLEX_ALIGN_END, 3);
            lv_obj_t *v = lv_label_create(row);

            lv_label_set_text(v, f_rows[i].value);
            lv_obj_set_style_text_font(v, sim_font_cjk(18), 0);
            lv_obj_set_style_text_color(v, lv_color_hex(F_INK), 0);
            lv_obj_t *u = lv_label_create(row);

            lv_label_set_text(u, f_rows[i].unit);
            lv_obj_set_style_text_font(u, sim_font_cjk(9), 0);
            lv_obj_set_style_text_color(u, lv_color_hex(F_MUTE), 0);
            lv_obj_set_style_pad_bottom(u, 2, 0);
        }
        if (i < 3) {
            f_hair(scr, 24, y + 21, 192);
        }
    }

    f_hair(scr, 0, 288, 240);
    d2_legend(scr, 300, 9, F_MUTE,
              "短按 #" F_INK_S " 1# 切页 · 长按 #" F_INK_S " 2# 结束");
}

/* ── 3. 导航页 ─────────────────────────────────────────────────── */

static void f_nav(lv_obj_t *scr)
{
    d_bg(scr, F_BG);

    /* 通栏地图（占位），道路白线 + 单一强调色路线。 */
    d_box(scr, 0, 0, 240, 152, F_MAP, LV_OPA_COVER, 0);
    d_box(scr, 0, 106, 240, 3, F_ROAD, LV_OPA_COVER, 0);
    d_box(scr, 96, 0, 3, 152, F_ROAD, LV_OPA_COVER, 0);
    {
        static lv_point_precise_t road[2] = { { 12, 142 }, { 228, 26 } };
        (void)d2_poly(scr, road, 2, 3, F_ROAD, true);
    }
    {
        static lv_point_precise_t rt[6] = {
            { 56, 150 }, { 56, 108 }, { 96, 108 }, { 96, 60 }, { 150, 60 },
            { 150, 20 },
        };
        (void)d2_poly(scr, rt, 6, 4, F_ACC, true);
    }
    d2_disc(scr, 56, 142, 9, F_INK);
    d2_disc(scr, 150, 20, 14, F_INK);
    d2_disc(scr, 150, 20, 7, F_CARD);

    /* 白色指令带：全宽，压在地图下沿。 */
    d_box(scr, 0, 152, 240, 56, F_CARD, LV_OPA_COVER, 0);
    {
        static lv_point_precise_t shaft[3] = { { 34, 196 }, { 34, 168 }, { 50, 168 } };
        static lv_point_precise_t head[3] = { { 45, 162 }, { 53, 168 }, { 45, 174 } };
        (void)d2_poly(scr, shaft, 3, 4, F_ACC, true);
        (void)d2_poly(scr, head, 3, 4, F_ACC, true);
    }
    d_label(scr, "300 m", 28, F_INK, 62, 158);
    d_label(scr, "右转 · 学院路", 10, F_MUTE, 146, 176);

    d_label(scr, "剩余", 9, F_MUTE, 24, 218);
    {
        lv_obj_t *row = d_stack(scr, 24, 226, 80, 28, LV_FLEX_ALIGN_START, 3);
        lv_obj_t *v = lv_label_create(row);

        lv_label_set_text(v, "8.4");
        lv_obj_set_style_text_font(v, sim_font_cjk(22), 0);
        lv_obj_set_style_text_color(v, lv_color_hex(F_INK), 0);
        lv_obj_t *u = lv_label_create(row);

        lv_label_set_text(u, "km");
        lv_obj_set_style_text_font(u, sim_font_cjk(9), 0);
        lv_obj_set_style_text_color(u, lv_color_hex(F_MUTE), 0);
        lv_obj_set_style_pad_bottom(u, 3, 0);
    }
    d_label(scr, "预计到达", 9, F_MUTE, 140, 218);
    d_label(scr, "9:14", 22, F_INK, 140, 226);
    d_vline(scr, 120, 216, 56, 0x000000u, 24);

    f_hair(scr, 0, 288, 240);
    d2_legend(scr, 300, 9, F_MUTE,
              "短按 #" F_INK_S " 1# 切页 · 长按 #" F_INK_S " 2# 结束");
}

/* ── 4. 菜单/设置页 ────────────────────────────────────────────── */

typedef struct {
    const char *name;
    const char *value;
} f_menu_row_t;

static const f_menu_row_t f_menu_rows[5] = {
    { "显示", "自动" },
    { "传感器", "3 个" },
    { "声音", "开" },
    { "关于", "v1.2.6" },
    { "关机", "" },
};

static void f_menu(lv_obj_t *scr)
{
    d_bg(scr, F_BG);

    d_label(scr, "设置", 28, F_INK, 24, 12);
    d_label_w(scr, "05", 11, F_MUTE, 160, 26, 56, LV_TEXT_ALIGN_RIGHT);

    for (int i = 0; i < 5; i++) {
        const int y = 64 + i * 40;
        const bool on = (i == 0);

        if (on) {
            d_box(scr, 0, y, 3, 40, F_ACC, LV_OPA_COVER, 0);
        }
        d_label(scr, i == 0 ? "01" : i == 1 ? "02" : i == 2 ? "03"
                       : i == 3 ? "04" : "05",
                9, on ? F_ACC : F_MUTE, 24, y + 15);
        d_label(scr, f_menu_rows[i].name, on ? 18 : 14,
                on ? F_INK : F_MUTE, 52, y + (on ? 9 : 12));
        if (f_menu_rows[i].value[0]) {
            d_label_w(scr, f_menu_rows[i].value, 10, F_MUTE, 140, y + 16,
                      56, LV_TEXT_ALIGN_RIGHT);
        }
        d_chevron(scr, 204, y + 16, on ? F_ACC : F_TRACK, 8);
        if (i < 4) {
            f_hair(scr, 24, y + 40, 192);
        }
    }

    f_hair(scr, 0, 288, 240);
    d2_legend(scr, 300, 9, F_MUTE,
              "短按 #" F_INK_S " 1# 下一项 · 长按 #" F_INK_S " 1# 进入 · 短按 #"
